const fmt=mins=>{mins=Math.max(0,Math.round(mins));const h=Math.floor(mins/60),m=mins%60;if(state.preferences.language==="bn")return h?`${h} ঘণ্টা ${m} মিনিট`:`${m} মিনিট`;return h?`${h}h ${m}m`:`${m}m`};
const allChapters=()=>state.subjects.flatMap(s=>s.papers.flatMap(p=>p.chapters.map(c=>({...c,subject:s,paper:p.paper}))));
const subjectById=id=>state.subjects.find(s=>s.subject===id);
const chapterById=id=>allChapters().find(c=>c.id===id);
const statusOf=c=>state.progress[c.id]?.status||(state.progress[c.id]?.done?"completed":"not-started");
const completedCount=items=>items.filter(c=>statusOf(c)==="completed").length;
const progressOf=items=>items.length?Math.round(completedCount(items)/items.length*100):0;
const sessionsFor=(date,subjectId)=>state.sessions.filter(s=>(!date||s.date===date)&&(!subjectId||s.subjectId===subjectId));
const totalMins=(list)=>list.reduce((n,s)=>n+s.minutes,0);
const minsToday=id=>totalMins(sessionsFor(todayKey(),id));
const revisionsFor=id=>state.revisions.filter(r=>r.chapterId===id).sort((a,b)=>b.timestamp.localeCompare(a.timestamp));
const lastRevision=id=>revisionsFor(id)[0]||null;
function recordRevision(chapterId){state.revisions.push({id:makeId(),chapterId,timestamp:new Date().toISOString()});save(KEYS.revisions,state.revisions);render()}
function seedProgressHistory(){if(state.progressHistory.length)return;const timestamp=new Date().toISOString();state.progressHistory=allChapters().map(c=>({chapterId:c.id,status:statusOf(c),timestamp,kind:"baseline"}));save(KEYS.progressHistory,state.progressHistory)}
function recordProgressChange(chapterId,status){state.progressHistory.push({chapterId,status,timestamp:new Date().toISOString(),kind:"change"});save(KEYS.progressHistory,state.progressHistory)}
function migrateProgress(){let changed=false;for(const c of allChapters()){const v=state.progress[c.id];if(v&& !v.status){state.progress[c.id]={...v,status:v.done?"completed":"not-started"};changed=true}}if(changed)save(KEYS.progress,state.progress)}
function migrateSessions(){let changed=false;state.sessions.forEach(s=>{if(!s.id){s.id=makeId();changed=true}});if(changed)save(KEYS.sessions,state.sessions);const t=state.timerData;if(t&&!t.id){t.id=makeId();save(KEYS.timer,t)}}
function applyTheme(){document.documentElement.dataset.theme=state.preferences.theme||"dark";const t=themes.find(x=>x[0]===state.preferences.theme)||themes[0];document.querySelector('meta[name="theme-color"]').content=t[2]}
