function subjectMinutes(id,from=null,to=null){return totalMins(state.sessions.filter(s=>s.subjectId===id&&(!from||s.date>=from)&&(!to||s.date<=to)))}
function selectedDateRange(days){const end=new Date();end.setHours(0,0,0,0);const start=new Date(end);start.setDate(end.getDate()-(days-1));return [todayKey(start),todayKey(end)]}
