function goalFeedback(actual,target){if(actual>=target)return state.preferences.language==="bn"?"আজকের পড়ার সময়ের লক্ষ্য পূরণ হয়েছে। চাইলে আগামীকালের লক্ষ্য ঠিক করতে পারো।":"You reached today’s study-time goal. You can set a new target for tomorrow.";return state.preferences.language==="bn"?`আজকের লক্ষ্যে পৌঁছাতে ${fmt(target-actual)} বাকি। এখন যতটুকু পড়া সম্ভব, সেটুকুও অগ্রগতি।`:`You’re ${fmt(target-actual)} short of today’s goal. Any focused time you add still counts.`}
