function render(){applyTheme();document.documentElement.lang=state.preferences.language==="bn"?"bn":"en";document.title=state.preferences.language==="bn"?"স্টাডিফ্লো — এইচএসসি ড্যাশবোর্ড":"Studyflow — HSC Dashboard";shell(state.page==="overview"?renderOverview():state.page==="syllabus"?renderSyllabus():state.page==="sessions"?renderSessions():state.page==="analytics"?renderAnalytics():state.page==="settings"?renderSettings():renderReview());themeDialog();startTick()}
