function init(){try{if(!state.subjects.length)throw new Error("subjects.js has no syllabus data");migrateProgress();migrateSessions();seedProgressHistory();save(KEYS.preferences,state.preferences);applyTheme();themeDialog();startFlow()}catch(error){console.error(error);app.replaceChildren(el("div","load-error","The syllabus data did not load. Keep subjects.js beside index.html, then reopen the page."))}}
